//! Interoperability fixtures produced by the Go oracle (`auth.HashPassword`).

use argon2::{
    Argon2,
    password_hash::{PasswordVerifier, phc::PasswordHash},
};
use azahar_auth::{hash_password, verify_password};

/// Generated by `backend/cmd/oracle-ids-auth` with the password below.
const GO_FIXTURES: &[(&str, &str)] = &[
    (
        "correct horse battery staple",
        "$argon2id$v=19$m=65536,t=3,p=4$Yx9XmONnbEG7bxWEGVqQ/A$2utVos2HFVU8JgOuTSaUR4+LnCqdeZCuD26AJWcA6I4",
    ),
    (
        "pässwörd 🔐",
        "$argon2id$v=19$m=65536,t=3,p=4$SW94LaYNE1MAO+9WeQ/tlw$hUbGrHVUdwY3F5a74fD9DJqnzR1hClCF231xs1KKRm8",
    ),
    (
        "",
        "$argon2id$v=19$m=65536,t=3,p=4$uh2WFtRg4SLWC0uKukuRTw$ybui2KbP7e73F5hGyATRqtX5rS49NzGMInJNdy+Fd7I",
    ),
    // Legal Argon2 parameters below the crate's preferred minimum but above
    // Go's clamped minimum, written by `argon2.IDKey(m=9,t=1,p=1)`.
    (
        "custom",
        "$argon2id$v=19$m=9,t=1,p=1$c2FsdHNhbHQ$N/PPtZ+GH4VAIfArdM3WnQ",
    ),
];

#[test]
fn go_hashes_verify_in_rust() {
    for (password, hash) in GO_FIXTURES {
        assert!(verify_password(password, hash), "{password}");
        assert!(!verify_password("definitely not the password", hash));
    }
}

#[test]
fn argon2_password_verifier_accepts_go_hashes() {
    for (password, hash) in GO_FIXTURES {
        let parsed = PasswordHash::new(hash).expect("Go PHC hash");
        Argon2::default()
            .verify_password(password.as_bytes(), &parsed)
            .expect("Argon2 verifier");
    }
}

#[test]
fn rust_hashes_have_the_go_phc_shape_and_parse() {
    let hash = hash_password("rust fixture").expect("hash");
    assert!(hash.starts_with("$argon2id$v=19$m=65536,t=3,p=4$"));

    let parsed = PasswordHash::new(&hash).expect("Rust PHC hash");
    assert_eq!(parsed.algorithm.as_str(), "argon2id");
    assert_eq!(parsed.version, Some(19));
    assert_eq!(parsed.params.get_str("m"), Some("65536"));
    assert_eq!(parsed.params.get_str("t"), Some("3"));
    assert_eq!(parsed.params.get_str("p"), Some("4"));

    let salt = parsed.salt.expect("salt").to_string();
    let key = parsed.hash.expect("hash").to_string();
    assert_eq!(salt.len(), 22);
    assert_eq!(key.len(), 43);
    assert!(!salt.contains('='));
    assert!(!key.contains('='));
}
